@CommandBuilder(CommandType.SLASH)
export class PingCommandBuilder implements CommandBuilderBase {
  build(commandName: string): SlashCommandBuilder {
    return new SlashCommandBuilder().setName(commandName).setDescription('Replies with pong')
  }
}
```

```typescript
@Controller()
export class PingSlashController {
  constructor(private pingService: PingService) {}

  @Command('ping', PingCommandBuilder)
  async ping(interaction: ChatInputCommandInteraction) {
    await interaction.reply(await this.pingService.handlePing())
  }
}
```

